import React from "react";
import {
  Card,
  CardContent,
  CardMedia,
  Typography,
  CardActionArea
} from "@mui/material";

const ProductCard = ({ product }) => {
  return (
    <Card sx={{ maxWidth: 300, m: 2 }}>
      <CardActionArea>
        <CardMedia
          component="img"
          height="200"
          image={`/${product.image}`}
          alt={product.name}
        />
        <CardContent>
          <Typography variant="h6" component="div">
            {product.name}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Price: ${product.price}
          </Typography>
        </CardContent>
      </CardActionArea>
    </Card>
  );
};

export default ProductCard;
